from io import StringIO
from reproduce import load_records
from Bio import SeqIO
from Bio.Seq import reverse_complement

records = load_records()
for record in records:
    moved = record.reverse_complement(id=record.id, name=record.name)
    source = {f.qualifiers['label'][0]: f for f in record.features}
    flipped = {f.qualifiers['label'][0]: f for f in moved.features}
    for label, feature in source.items():
        transformed = flipped[label]
        old_parts = [part.extract(record.seq) for part in feature.location.parts]
        new_parts = [part.extract(moved.seq) for part in transformed.location.parts]
        strands = [part.strand for part in feature.location.parts]
        if all(strand not in (-1, 1) for strand in strands):
            assert transformed.extract(moved.seq) == reverse_complement(feature.extract(record.seq)), (record.id, label)
            assert new_parts == [reverse_complement(part) for part in old_parts[::-1]], (record.id, label)
        else:
            expected_parts = [
                part if strand in (-1, 1) else reverse_complement(part)
                for part, strand in zip(old_parts, strands)
            ]
            assert new_parts == expected_parts, (record.id, label, old_parts, new_parts, expected_parts)
        assert transformed.location._flip(len(record)) == feature.location, (record.id, label)

buffer = StringIO()
for record in records:
    moved = record.reverse_complement(id=record.id, name=record.name)
    moved.description = record.description
    moved.annotations['molecule_type'] = record.annotations['molecule_type']
    moved.annotations['topology'] = record.annotations['topology']
    SeqIO.write(moved, buffer, 'genbank')
buffer.seek(0)
delivered = {record.id: record for record in SeqIO.parse(buffer, 'genbank')}
for record in records:
    source = {f.qualifiers['label'][0]: f for f in record.features}
    output = {f.qualifiers['label'][0]: f for f in delivered[record.id].features}
    for label, feature in source.items():
        strands = [part.strand for part in feature.location.parts]
        if all(strand not in (-1, 1) for strand in strands):
            expected = reverse_complement(feature.extract(record.seq))
            assert output[label].extract(delivered[record.id].seq) == expected, (record.id, label)
print('feature transformation and GenBank round-trip diagnostics passed')
PY"

